static int petal(p2d89_u16 rot,p2d89_q14 len,p2d89_q14 wid,const P2D89_Provider *p){p2d89_q14 a,b,c,d,e,f,g,h,j,k,l,m;pt(0,0,rot,&a,&b);pt((p2d89_q14)(len/2),(p2d89_q14)-wid,rot,&c,&d);pt(len,(p2d89_q14)-wid,rot,&e,&f);pt(len,0,rot,&g,&h);pt(len,wid,rot,&j,&k);pt((p2d89_q14)(len/2),wid,rot,&l,&m);if(!p2d89_i_move(p,a,b))return 0;if(!p2d89_i_cubic(p,c,d,e,f,g,h))return 0;if(!p2d89_i_cubic(p,j,k,l,m,a,b))return 0;return p2d89_i_close(p);}
