static int emit(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 fleur[]={0,-16384,4096,-8192,8192,-12288,7168,-4096,14336,-6144,8192,2048,6144,8192,2048,7168,0,14336,-2048,7168,-6144,8192,-8192,2048,-14336,-6144,-7168,-4096,-8192,-12288,-4096,-8192};if(id==P2D89_SHAPE_QUATREFOIL){if(!circle_at(0,-6144,7168,p))return 0;if(!circle_at(6144,0,7168,p))return 0;if(!circle_at(0,6144,7168,p))return 0;return circle_at(-6144,0,7168,p);}if(id==P2D89_SHAPE_TREFOIL){if(!circle_at(0,-5632,7168,p))return 0;if(!circle_at(4864,2816,7168,p))return 0;return circle_at(-4864,2816,7168,p);}if(id==P2D89_SHAPE_CLOVER_4)return rosette(4U,p);if(id==P2D89_SHAPE_ROSETTE_4)return rosette(4U,p);if(id==P2D89_SHAPE_ROSETTE_6)return rosette(6U,p);if(id==P2D89_SHAPE_ROSETTE_8)return rosette(8U,p);if(id==P2D89_SHAPE_ROSETTE_12)return rosette(12U,p);if(id==P2D89_SHAPE_PETAL)return petal(49152U,16384,5120,p);if(id==P2D89_SHAPE_PETAL_PAIR){if(!petal(0U,14336,4096,p))return 0;return petal(32768U,14336,4096,p);}if(id==P2D89_SHAPE_LEAF)return p2d89_i_lens(7168,p);if(id==P2D89_SHAPE_LEAF_PAIR){if(!petal(8192U,14336,3584,p))return 0;return petal(24576U,14336,3584,p);}if(id==P2D89_SHAPE_FLEUR_DE_LIS_SIMPLIFIED)return p2d89_i_poly(fleur,16U,1,p);return 0;}
